import{_ as a}from"./chunks/d7934098438af5ce408b.Dba7sCv-.js";import{_ as o,C as r,o as i,c as l,j as e,a as n,E as h,a5 as s}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"NPC之路（如何避免平庸的一生）","description":"","frontmatter":{"title":"NPC之路（如何避免平庸的一生）","originalTitle":"The Path Of The NPC (How To Not End Up Mediocre)","date":"2023-04-29","originalUrl":"https://thedankoe.com/letters/the-path-of-the-npc-how-to-not-end-up-mediocre/","minutes":7,"sourceHash":"88e8eb757597ed1ac10743072bdb61596f84740ae59ee00ac1bce3f92ae40d23","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-path-of-the-npc-how-to-not-end-up-mediocre/"}]]},"headers":[],"relativePath":"letters/the-path-of-the-npc-how-to-not-end-up-mediocre.md","filePath":"letters/the-path-of-the-npc-how-to-not-end-up-mediocre.md"}'),c={name:"letters/the-path-of-the-npc-how-to-not-end-up-mediocre.md"};function d(m,p,u,f,P,_){const t=r("ArticleMeta");return i(),l("div",null,[p[0]||(p[0]=e("h1",{id:"npc之路-如何避免平庸的一生",tabindex:"-1"},[n("NPC之路（如何避免平庸的一生） "),e("a",{class:"header-anchor",href:"#npc之路-如何避免平庸的一生","aria-label":'Permalink to "NPC之路（如何避免平庸的一生）"'},"​")],-1)),h(t),p[1]||(p[1]=s('<p><a href="https://www.youtube.com/embed/r1LI1-K08II?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>你从出生起就一直在模仿别人。</p><p>这是你学习在社会中运作的方式。</p><p>这会导致两条不同的道路：</p><h3 id="_1-npc之路" tabindex="-1">1) NPC之路 <a class="header-anchor" href="#_1-npc之路" aria-label="Permalink to &quot;1) NPC之路&quot;">​</a></h3><p>NPC，即非玩家角色（non-player character），是受制于自身程序的奴隶。</p><p>他们从不质疑自己的信念（你知道的，就是那些被投射到他们身上，而他们毫无反抗就接受了的信念）。</p><p>他们从不寻求改变。</p><p>上学、找工作、65岁退休，这条默认的路径是他们仅有的远大目标。</p><p>他们从不涉足未知领域。</p><p>他们的生活变得无聊、机械、如同动物一般。他们从不发掘自己生活的新潜能。就算发现了，也会被吓得缩回自己舒适的洞穴里。</p><h3 id="_2-主角之路" tabindex="-1">2) 主角之路 <a class="header-anchor" href="#_2-主角之路" aria-label="Permalink to &quot;2) 主角之路&quot;">​</a></h3><p>主角是对未来有清晰愿景的人，他们拥有为了实现愿景而自发设定的目标，以及每天必须执行的、没有任何商量余地的行动。</p><p>他们很清楚，传统的职业道路通向的只是你在99%的人口身上能观察到的那种平庸的生活方式。</p><p>他们明白，自己必须对自己的生活负责。</p><p>他们明白，自己没有任何理所应当的特权。无论胜算几何，他们都必须亲手去创造成功。</p><p><strong>提醒</strong>：如你所知，Solopreneur Sprints（建立你的一人企业基础）将于15号开始。<a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">在此报名</a>。</p><h2 id="你是主观现实中的视角容器" tabindex="-1">你是主观现实中的视角容器 <a class="header-anchor" href="#你是主观现实中的视角容器" aria-label="Permalink to &quot;你是主观现实中的视角容器&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>现实即视角，而你是一个视角的容器。</p><p>NPC和主角之所以以各自的方式在现实中穿梭，是因为他们的视角不同。</p><p>你的视角是随着时间推移通过后天塑造（conditioning）锻造而成的。</p><p>塑造（Conditioning）= 你用大脑处理的信息随时间不断重复，直到这些思维过程变成自动自发。</p><p>视角与身份认同密切相关。</p><p>乔·迪斯彭扎（Joe Dispenza）有句名言：</p><p>“你的个性创造了你的个人现实。”</p><p>你的身份认同（你对自己是谁的认知）会影响三个主要方面：</p><ul><li>你的视角或世界观</li><li>你从该视角看待事物的方式</li><li>你基于这两者所做出的选择</li></ul><p>NPC的视角是封闭的，局限于社会投射给他们的目标。</p><p>NPC对他们在意识中接收到的信念、想法和思绪产生认同。</p><p>因为他们有着“普通人”的身份认同，他们会感到被驱使着去做与之一致的事情。</p><p>他们会：</p><ul><li>结交相似的朋友</li><li>改变自己的外表（为了融入群体）</li><li>消费那些能强化这种身份认同的电影、媒体和信息</li></ul><p>所有这些都让他们的头脑局限在生活中特定的问题和潜能上。</p><p>对于NPC来说，这些问题通常包括支付账单、在公司的权力阶梯上晋升，以及为了退休东拼西凑地存点钱。</p><p>他们消费的大部分信息都是负面的、极端的、博人眼球的，这些信息将他们牢牢锁在枷锁之中。</p><p>对社会最危险的威胁，是那些不依赖社会的人。</p><p>从这种被塑造的视角出发，NPC就会以此来解读各种情况和机遇。</p><p>当有人向他们展示商业机会时，比如建立个人品牌，他们的脑海里就会涌现出父母、学校和新闻媒体植入给他们的各种借口和防御机制。</p><p>当有人鼓励他们锻炼身体时，他们会用新闻媒体灌输给他们的任何说辞进行攻击，以此来为自己辩护。</p><p>你的任务，就是去觉察你心智中的程序设定。</p><p>只有这样，你才能成为自己故事里的主角。</p><p>在一个推崇平庸的社会中，你被环境塑造出了某种身份认同。你必须意识到这一点，并努力去改变它。</p><p>改变你是谁是一件难事，而且没人能替你做。</p><p>它需要刻意为之，也需要付出努力。</p><h2 id="智能模仿过程-成为主角" tabindex="-1">智能模仿过程（成为主角） <a class="header-anchor" href="#智能模仿过程-成为主角" aria-label="Permalink to &quot;智能模仿过程（成为主角）&quot;">​</a></h2><p>要开始为了成功去重塑你的心智，你必须：</p><ul><li>为更高质量的生活设定新目标</li><li>让自己沉浸在能够塑造新视角的信息中</li><li>取得进展，并关注它给你的生活带来的积极成果。</li></ul><p>从最重要的事情开始：</p><p>你的头脑、身体、精神和财务。</p><p>一个重视健身的人，比如健美运动员，会做出通向更高质量生活的选择。</p><p>这已经深深烙印在他们的身份认同中了。</p><p>他们会吃健康的食物，努力训练，并避开那些有损于他们进步的情况。</p><p>同样的情况也适用于那些重视建立企业、传播善意，并渴望拥有机智明智头脑的人。</p><p>他们所做的选择会带来更充沛的精力、更少的财务压力，以及从智力发展中获得更深层次的满足感。</p><p>大多数人会认为，他们应该努力停止抄袭、模仿，或者停止被信息所塑造。</p><p>那是不可能的。</p><p>模仿是你学习的方式。</p><p>NPC和主角之间的区别在于，后者是用一种智慧或带有意识的头脑在模仿。</p><p>他们<em>意识到</em>自己正在模仿什么，以及这会如何影响他们的生活。</p><p>NPC会模仿羊群，走上跟大众相同的道路。</p><p>主角则会模仿那些他们认为成功的人，而这些人的成功与他们想要创造的未来是一致的。</p><h3 id="步骤-1-创造一个你可以-长成-的视角。" tabindex="-1">步骤 1) 创造一个你可以“长成”的视角。 <a class="header-anchor" href="#步骤-1-创造一个你可以-长成-的视角。" aria-label="Permalink to &quot;步骤 1) 创造一个你可以“长成”的视角。&quot;">​</a></h3><p>视角即现实。</p><p>如果你想创造自己的现实，你就必须创造一个新的视角。</p><p>你创造的视角将为你提供一个审视当下处境的镜头。</p><p>你通过有意识的练习“长成”（融入）那个视角。</p><p>回答以下问题：</p><ul><li>我理想的一天是什么样的？</li><li>我想要把什么作为我毕生的事业？</li><li>我想要如何影响他人的生活？</li><li>我想要拥有怎样的外表和感觉？</li><li>我需要采取什么样的价值观和习惯，才能让这些变为现实？</li></ul><p>从此开始，在度过每一天时，练习带入你未来自我的视角。</p><p>刚开始会很困难，但你将开始发现可以采取行动的问题和机遇。</p><h3 id="步骤-2-选择3-5位你渴望成为其那样的人的-导师-。" tabindex="-1">步骤 2) 选择3-5位你渴望成为其那样的人的“导师”。 <a class="header-anchor" href="#步骤-2-选择3-5位你渴望成为其那样的人的-导师-。" aria-label="Permalink to &quot;步骤 2) 选择3-5位你渴望成为其那样的人的“导师”。&quot;">​</a></h3><p><em>你消费什么就会成为什么，所以请</em> <em>根据你想成为的人</em> <em>进行消费。</em></p><p>为了让这个过程变简单，写下3-5个改变了<em>你</em>的视角的那些人的名字。</p><p>你最喜欢并逢人就推荐的书是什么？写下作者的名字。</p><p>你忍不住一直看的YouTuber、播客主播或博主是谁？是哪个每次一发内容都能让你“大开眼界”的人？</p><p>你关注了哪些社交媒体账号，让你经常感叹：“他们怎么能说得这么好？”</p><p>因为这就是问题所在……并不是每个人都这么想。只有你。将这些“导师”结合并<em>串联</em>起来，就是你开创自己的细分领域（niche）、视角和内容，从而让你脱颖而出的方式。</p><p>重新读一遍你最喜欢的书的第一章——我保证你的大脑会被点亮。</p><h3 id="步骤-3-成为一个疯狂科学家。" tabindex="-1">步骤 3) 成为一个疯狂科学家。 <a class="header-anchor" href="#步骤-3-成为一个疯狂科学家。" aria-label="Permalink to &quot;步骤 3) 成为一个疯狂科学家。&quot;">​</a></h3><p>美好的生活就是一系列的实验。</p><p>你无法从别人那里照搬。你必须去尝试、去失败，去收集那些能让你个人生活变得伟大的碎片。</p><p>NPC只接受摆在他们面前的东西。</p><p>主角则倾心于能够反映大自然进化与成长规律的试错过程。</p><p>当你沉浸在导师提供的信息中并向着目标推进时，请遵循科学的流程。</p><ul><li><strong>研究</strong> – 不要无脑地消费内容。收集信息是为了将它们应用到你的目标上。</li><li><strong>测试</strong> – 不要把建议或信息奉为圭臬。测试它是否适用于你的情况。</li><li><strong>实验</strong> – 不要对某一种方法过于教条。尝试不同的饮食习惯、商业模式和宗教意识形态，直到它们各自的真理在中间交汇模糊。</li><li><strong>发现</strong> – 注意那些能够产生符合你目标结果的规律。</li><li><strong>记录</strong> – 写下那些让你获得成果的东西。这是你可以出售或利用杠杆作用的有价值的信息。</li></ul><p>当你把生活当作一个项目来对待时，它就会变得有利可图。</p><p>个人品牌只不过是在公众面前发掘自我，并通过你所做的研究获得报酬。</p><h3 id="步骤-4-创造-或者被创造。" tabindex="-1">步骤 4) 创造，或者被创造。 <a class="header-anchor" href="#步骤-4-创造-或者被创造。" aria-label="Permalink to &quot;步骤 4) 创造，或者被创造。&quot;">​</a></h3><p>NPC和主角之间的主要区别在于创造。</p><p>NPC是在多年无意识的环境塑造中被创造出来的。</p><p>主角则是通过多年有意识的塑造被创造出来的（他们主动选择自己的信息输入）。</p><p>没有人能逃脱塑造。</p><p>它正在你周围发生着。</p><p>这封信正在塑造你。希望能朝着好的方向发展。</p><p>现代世界，要么你去创造，要么你被创造。</p><p>选择权在于你（在每一天的每一毫秒中）。</p><p>享受你的周末。</p><p>– 丹</p><p>P.S. Solopreneur Sprints将于5月15日开始。</p><p>如果你想用我的品牌和高绩效内容系统来建立你的一人企业基础，<a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">点击这里查看</a>。</p><p>数字经济学（Digital Economics）的价格也将在那一天翻倍。你可以在同一个页面上找到它。</p><hr><p><a href="/en/letters/the-path-of-the-npc-how-to-not-end-up-mediocre">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',104))])}const C=o(c,[["render",d]]);export{g as __pageData,C as default};
